package kaitai

import (
	"bytes"
	"compress/zlib"
	"encoding/hex"
	"math/rand"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestUnprocessZlibCompactVectors(t *testing.T) {
	// Independently generated by Java Deflater's defaults and Python zlib.compress.
	// These small encodings must fit their existing fixed-size serialized fields.
	for _, tc := range []struct {
		name string
		data []byte
		want string
	}{
		{"empty", nil, "789c030000000001"},
		{"one literal", []byte("a"), "789c4b040000620062"},
		{"zlib_surrounded", []byte{255, 255, 255, 255}, "789cfbffffff7f0009fa03fd"},
		{"changed child", []byte{254, 255, 255, 255}, "789cfbf7ffff7f0009f603fc"},
		{"zlib_with_header_78", []byte("a quick brown fox jumps over"),
			"789c4b54282ccd4cce56482aca2fcf5348cbaf50c82acd2d2856c82f4b2d020094bd0a7f"},
		{"changed text", []byte("goodbye, world"), "789c4bcfcf4f49aa4cd55128cf2fca49010028a5055e"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			want, err := hex.DecodeString(tc.want)
			require.NoError(t, err)
			got, err := UnprocessZlib(tc.data)
			require.NoError(t, err)
			require.Equal(t, want, got)
			decoded, err := ProcessZlib(got)
			require.NoError(t, err)
			require.True(t, bytes.Equal(tc.data, decoded))
			buf := NewFixedSeekableBuffer(len(want))
			require.NoError(t, NewWriter(buf).WriteBytes(got))
			require.Equal(t, want, buf.Bytes())
			short := NewFixedSeekableBuffer(len(want) - 1)
			require.ErrorIs(t, NewWriter(short).WriteBytes(got), ErrBufferCapacity)
			require.Equal(t, make([]byte, len(want)-1), short.Bytes())
		})
	}
}

func TestUnprocessZlibCompressionAndBoundaries(t *testing.T) {
	random := make([]byte, 131073)
	_, err := rand.New(rand.NewSource(1)).Read(random) //nolint:gosec // Repeatable compression input, not security data.
	require.NoError(t, err)
	for _, data := range [][]byte{
		{0, 143, 144, 255}, bytes.Repeat([]byte{143, 144}, 7),
		bytes.Repeat([]byte("a"), 131073), random,
	} {
		original := bytes.Clone(data)
		var standard bytes.Buffer
		writer := zlib.NewWriter(&standard)
		_, err := writer.Write(data)
		require.NoError(t, err)
		require.NoError(t, writer.Close())
		got, err := UnprocessZlib(data)
		require.NoError(t, err)
		require.LessOrEqual(t, len(got), standard.Len(), "compact encoding worsened compression")
		decoded, err := ProcessZlib(got)
		require.NoError(t, err)
		require.Equal(t, data, decoded)
		require.Equal(t, original, data)
	}
	// Exercise every literal code and final-byte alignment with short payloads.
	for value := range 256 {
		for size := 1; size <= 8; size++ {
			data := bytes.Repeat([]byte{byte(value)}, size)
			got, err := UnprocessZlib(data)
			require.NoError(t, err)
			decoded, err := ProcessZlib(got)
			require.NoError(t, err)
			require.Equal(t, data, decoded)
		}
	}
}
